Code.NativeIaC:
```bicep
// Enable Blob service diagnostic logging for read, write and delete
param storageAccountName string
param workspaceId string

resource sa 'Microsoft.Storage/storageAccounts@2023-01-01' existing = {
  name: storageAccountName
}

resource blobService 'Microsoft.Storage/storageAccounts/blobServices@2023-01-01' existing = {
  parent: sa
  name: 'default'
}

resource diag 'Microsoft.Insights/diagnosticSettings@2021-05-01-preview' = {
  name: '<example_resource_name>'
  scope: blobService
  properties: {
    workspaceId: workspaceId
    logs: [
      { category: 'StorageRead', enabled: true }   // Critical: enables read logging
      { category: 'StorageWrite', enabled: true }   // Critical: enables write logging
      { category: 'StorageDelete', enabled: true }  // Critical: enables delete logging
    ]
  }
}
```

Code.Terraform:
```hcl
# Enable Blob service diagnostic logging
resource "azurerm_monitor_diagnostic_setting" "<example_resource_name>" {
  name                       = "<example_resource_name>"
  target_resource_id         = "${azurerm_storage_account.<example_resource_name>.id}/blobServices/default"
  log_analytics_workspace_id = "<example_resource_id>"

  enabled_log {
    category = "StorageRead"  # Critical: enables read logging
  }
  enabled_log {
    category = "StorageWrite"  # Critical: enables write logging
  }
  enabled_log {
    category = "StorageDelete"  # Critical: enables delete logging
  }
}
```
